package psx.exporter;
import java.nio.*;
import java.nio.file.*;
import java.util.*;
import java.io.*;
final class SituationLayer {
 record Result(Map<String,byte[]> overlay,List<String> evidence){}
 static Result bounded(Result r,int lowerBytes){if(r.overlay.values().stream().anyMatch(b->b.length>1024*1024)||lowerBytes+r.overlay.values().stream().mapToInt(b->b.length).sum()>8*1024*1024)return new Result(Map.of(),List.of("situation unavailable: complete preparation budget exceeded"));return r;}
 static boolean available(){try{if(SituationNative.abiVersion()!=1||SituationNative.initialize(false))return false;SituationNative.capabilities(0);SituationNative.poll(ByteBuffer.allocateDirect(64),0);SituationNative.begin(0,0);SituationNative.complete(0,0,0,0,0,null,0,null);SituationNative.sourceHash(null);return true;}catch(Throwable unavailable){return false;}}
 static Result prepare(Prepare base,Map<String,byte[]> lower,String jarHash){SituationPrepare p=new SituationPrepare(base);try{if(!"96b7504a58920794394ff0b7b6a4e33189a37965e836119e845a34164ede8285".equalsIgnoreCase(jarHash))throw new IOException("native situation installed JAR qualification differs");if(!available())throw new IOException("situation JNI1 unavailable");p.auditInstalled();p.qualify();return new Result(p.transform(lower),List.copyOf(p.evidence));}catch(Throwable unavailable){p.evidence.add("situation unavailable: "+unavailable);return new Result(Map.of(),List.copyOf(p.evidence));}}
 static void write(Result r,Prepare base,Map<String,byte[]> lower,Path output,Properties p)throws Exception{p.setProperty("situation.capabilities",r.overlay.isEmpty()?"0":"15");Files.createDirectories(output.resolve("situation-classes"));for(var e:r.overlay.entrySet()){Files.write(output.resolve("situation-classes/"+e.getKey()+".class"),e.getValue(),StandardOpenOption.CREATE_NEW);p.setProperty(e.getKey()+".situation.original",Identity.hash(base.inputs.get(e.getKey())));p.setProperty(e.getKey()+".situation.base",Identity.hash(lower.getOrDefault(e.getKey(),base.inputs.get(e.getKey()))));p.setProperty(e.getKey()+".situation.prepared",Identity.hash(e.getValue()));}Files.write(output.resolve("situation-inventory.txt"),r.evidence,StandardOpenOption.CREATE_NEW);}
 static Map<String,byte[]> read(Properties p,Path root,Map<String,String> originals,Map<String,byte[]> lower)throws Exception{if(!"15".equals(p.getProperty("situation.capabilities")))return Map.of();String name="SituationFiler",orig=originals.get(name);if(orig==null||!orig.equals(p.getProperty(name+".situation.original"))||!Objects.equals(lower.containsKey(name)?Identity.hash(lower.get(name)):orig,p.getProperty(name+".situation.base")))throw new IOException("situation lower identity");byte[] bytes;try(var in=Files.newInputStream(root.resolve("situation-classes/SituationFiler.class"))){bytes=in.readNBytes(1024*1024+1);}if(bytes.length>1024*1024||!Identity.hash(bytes).equals(p.getProperty(name+".situation.prepared")))throw new IOException("situation prepared identity");return Map.of(name,bytes);}
}
